// ============================================================
// CONFIG - Founders text campaign in batches (see README.md)
// ============================================================
return [{ json: {
  LOCATION_ID: 'XTpY4DQ6CrYVvesFdX3K',
  SECRET: 'VTNLn3qmT0Sw2dcuICHPBtNdeBqA2BzQCKUaUpmN',            // the bar site API (workflow 6) calls this workflow with it; keep both the same
  BATCHES: 6,                      // contacts are tagged founders-batch-1 ... founders-batch-6
  BATCH_TAG: 'founders-batch-',
  SEND_TAG: 'founders-send',       // the GHL workflow "Founders Essential Text Blast" starts when this tag is added
  TEXT_TAGS: ['founders-text-1-sent', 'founders-text-2-sent', 'founders-text-3-sent'], // added by that workflow after each text
  TIMEZONE: 'America/Denver',      // "today" for the one-batch-a-day rule (SMS limit is 500 a day)
}}];

// Checks the secret and the request. A batch can be started once, and only one batch a day (the daily SMS limit).
const cfg = $('Config').first().json;
const body = $('Campaign Webhook').first().json.body || {};
const fail = (msg) => [{ json: { ok: false, error: msg } }];
if (!cfg.SECRET || body.secret !== cfg.SECRET) return fail('Not allowed');
const action = body.action === 'campaign-send' ? 'send' : 'status';
const state = $getWorkflowStaticData('global');
state.campaign = state.campaign || { batches: {} };
const today = new Date().toLocaleDateString('en-CA', { timeZone: cfg.TIMEZONE });
if (action === 'send') {
  const batch = parseInt(body.batch, 10);
  if (!(batch >= 1 && batch <= cfg.BATCHES)) return fail('Unknown batch');
  const b = state.campaign.batches;
  if (b[batch]) return fail('Batch ' + batch + ' was already started');
  const other = Object.keys(b).find((k) => b[k].startedDate === today);
  if (other) return fail('Batch ' + other + ' was already started today. Send one batch a day to stay under the SMS limit.');
  b[batch] = { startedAt: new Date().toISOString(), startedDate: today };
  return [{ json: { ok: true, action, batch } }];
}
return [{ json: { ok: true, action, batch: 0 } }];

// One search page per 100 contacts: the batch being started, or all batches for the status view.
const cfg = $('Config').first().json;
const c = $('Check').first().json;
const batches = c.action === 'send' ? [c.batch] : Array.from({ length: cfg.BATCHES }, (_, i) => i + 1);
const items = [];
for (const batch of batches) for (let page = 1; page <= 6; page++) items.push({ json: { batch, page } });
return items;

// Sends: the contacts of the batch to tag. Status: counts per batch.
const cfg = $('Config').first().json;
const c = $('Check').first().json;
const pages = $('Pages').all();
const by = {};
$input.all().forEach((it, i) => {
  const b = pages[i] && pages[i].json.batch;
  for (const x of (it.json.contacts || [])) { (by[b] = by[b] || new Map()).set(x.id, x); }
});
const state = $getWorkflowStaticData('global');
state.campaign = state.campaign || { batches: {} };
if (c.action === 'send') {
  const list = [...(by[c.batch] || new Map()).values()];
  state.campaign.batches[c.batch].queued = list.length;
  return list.map((x) => ({ json: { id: x.id, status: false } }));
}
const has = (x, t) => (x.tags || []).some((g) => String(g).toLowerCase() === t);
const batches = [];
for (let b = 1; b <= cfg.BATCHES; b++) {
  const list = [...(by[b] || new Map()).values()];
  const st = state.campaign.batches[b] || null;
  batches.push({
    batch: b,
    total: list.length,
    texts: cfg.TEXT_TAGS.map((t) => list.filter((x) => has(x, t)).length),
    started: !!st,
    startedAt: st ? st.startedAt : '',
    startedDate: st ? st.startedDate : '',
    queued: st && st.queued != null ? st.queued : 0,
    finishedAt: st && st.finishedAt ? st.finishedAt : '',
    sending: !!(st && !st.finishedAt),
  });
}
return [{ json: { status: true, batches, today: new Date().toLocaleDateString('en-CA', { timeZone: cfg.TIMEZONE }), updatedAt: new Date().toISOString() } }];

// All contacts of the batch are tagged: the GHL workflow now sends the texts.
const c = $('Check').first().json;
const state = $getWorkflowStaticData('global');
if (state.campaign && state.campaign.batches[c.batch]) state.campaign.batches[c.batch].finishedAt = new Date().toISOString();
return [{ json: { ok: true, batch: c.batch } }];
